"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["35901"],{72709(e){e.exports=JSON.parse('{"id":"V4-213","slug":"biometric-authentication","term":"Biometric Authentication","also_known_as":[],"difficulty":"Beginner","definition":"Biometric authentication is a security method that verifies a person\u2019s identity using unique physical or behavioural characteristics, such as fingerprints, facial features, voice or typing patterns.","explanation":["Instead of relying only on something a person knows, such as a password, biometric authentication uses something a person is. Common forms in financial services include fingerprint scanning, facial recognition, voice recognition and iris scanning.","Behavioural biometrics analyse patterns in how people interact with devices, such as typing speed, how they hold their phone or how they move a mouse, which can help detect fraud during a session.","For example, a banking app may allow customers to log in and approve payments using their phone\u2019s fingerprint sensor or facial recognition, rather than typing a password.","Biometric authentication is convenient and harder to steal or guess than passwords. It is often used as one factor in multi-factor authentication and supports strong customer authentication rules, such as those under the European Union\u2019s Payment Services Directive.","However, biometrics raise concerns. Unlike passwords, biometric characteristics cannot be changed if stolen. They can raise privacy issues, and some systems may be fooled by fake images, recordings or deepfakes. Regulations such as the General Data Protection Regulation treat biometric data as especially sensitive. Firms must protect stored biometric data carefully."],"note":"","total":1725,"prev":{"slug":"binomial-option-pricing-model","term":"Binomial Option Pricing Model"},"next":{"slug":"bitcoin","term":"Bitcoin"}}')}}]);